// One-word interjections. `character` is a cast id (humor/cast.json): the line is recorded in that voice.
export const VOICE_LINES = {
  'announcer-oh': { character: 'announcer', text: 'Oh!', types: ['crash', 'scream', 'general'] },
  'announcer-folks': { character: 'announcer', text: 'Folks!', types: ['crash', 'panic', 'lucky_win', 'general'] },
  'announcer-unbelievable': { character: 'announcer', text: 'Unbelievable!', types: ['lucky_win', 'crash', 'general'] },
  'tired-great': { character: 'tired', text: 'Great.', types: ['crash', 'rage_quit', 'panic', 'general'] },
  'tired-wow': { character: 'tired', text: 'Wow.', types: ['lucky_win', 'silence', 'general'] },
  'tired-oh-good': { character: 'tired', text: 'Oh good.', types: ['crash', 'silence', 'rage_quit', 'general'] },
  'kid-whoa': { character: 'kid', text: 'Whoa!', types: ['crash', 'lucky_win', 'scream', 'panic', 'general'] },
  'kid-noway': { character: 'kid', text: 'No way!', types: ['lucky_win', 'scream', 'panic', 'general'] },
  'kid-hehe': { character: 'kid', text: 'Hehehe!', types: ['crash', 'rage_quit', 'silence', 'general'] },
  'grandma-dear': { character: 'grandma', text: 'Oh dear.', types: TYPES },
  'grandma-my': { character: 'grandma', text: 'Oh my.', types: ['crash', 'scream', 'lucky_win', 'general'] },
  'grandma-bless': { character: 'grandma', text: 'Bless.', types: ['rage_quit', 'general'] },
  'classic-ha': { character: 'classic', text: 'Ha!', types: TYPES },
  'classic-oof': { character: 'classic', text: 'Oof.', types: ['crash', 'rage_quit', 'panic'] },
};

export const CHARACTER_LABEL = { announcer: 'Announcer', tired: 'Tired Friend', kid: 'Kid', grandma: 'Grandma', classic: 'Classic' };

export const sfxFile = (id) => `sounds/${id}.mp3`;
export const voiceFile = (id) => `voices/${id}.mp3`;
export const bankFiles = () => [
  ...Object.keys(SFX).map((id) => ({ id, url: sfxFile(id) })),
  ...Object.keys(VOICE_LINES).map((id) => ({ id, url: voiceFile(id) })),
];

// ---------- picking ----------
const has = (list, x) => list.includes(x);

// Never the same choice twice in a row when there is another one.
function choose(ids, avoid, rand) {
  const pool = ids.length > 1 ? ids.filter((id) => id !== avoid) : ids;
  return pool.length ? pool[Math.floor(rand() * pool.length)] : null;
}

// SFX with the given role that fit the moment type and level. Falls back (level first, then type -> general)
// so there is always something to play.
function sfxFor(role, type, level) {
  const withRole = Object.entries(SFX).filter(([, s]) => has(s.roles, role));
  const tiers = [
    withRole.filter(([, s]) => has(s.types, type) && has(s.levels, level)),
    withRole.filter(([, s]) => has(s.types, type)),
    withRole.filter(([, s]) => has(s.types, 'general') && has(s.levels, level)),
    withRole.filter(([, s]) => has(s.types, 'general')),
  ];
  const hit = tiers.find((t) => t.length);
  return hit ? hit.map(([id]) => id) : [];
}

// The layers that start the moment a roast is triggered: an opening sound, then (usually) another
// character's interjection a moment later. `main` is who will speak the roast (or null if not known yet).
export function pickPre({ type = 'general', main = null, level = 'spicy', last = {} } = {}, rand = Math.random) {
  const pre = [];
  const open = choose(sfxFor('open', type, level), last.open, rand);
  if (open) pre.push({ id: open, kind: 'sfx', at: 0, gain: 0.8, label: SFX[open].label });

  const lines = Object.entries(VOICE_LINES)
    .filter(([, v]) => v.character !== main && (has(v.types, type) || has(v.types, 'general')))
    .map(([id]) => id);
  const line = rand() < 0.85 ? choose(lines, last.line, rand) : null;
  if (line) {
    const v = VOICE_LINES[line];
    pre.push({ id: line, kind: 'voice', at: 280 + Math.floor(rand() * 120), gain: 1, label: `${CHARACTER_LABEL[v.character]}: “${v.text}”` });
  }
  return pre;
}

// A quiet loop under the roast (only some moments have one, e.g. crickets under a silence).
export function pickBed({ type = 'general', level = 'spicy' } = {}, rand = Math.random) {
  const id = choose(sfxFor('bed', type, level).filter((i) => has(SFX[i].types, type)), null, rand);
  return id ? { id, kind: 'sfx', gain: 0.28, label: SFX[id].label } : null;
}

// The sting after the last word. Not every roast gets one (about 7 in 10), so it stays a treat.
export function pickSting({ type = 'general', level = 'spicy', last = {} } = {}, rand = Math.random) {
  if (rand() >= 0.7) return null;
  const id = choose(sfxFor('sting', type, level), last.sting, rand);
  return id ? { id, kind: 'sfx', at: 100 + Math.floor(rand() * 120), gain: 0.85, label: SFX[id].label } : null;
}

// The whole score at once (used by tests and for describing a roast).
export function pickScore(opts = {}, rand = Math.random) {
  return { pre: pickPre(opts, rand), bed: pickBed(opts, rand), sting: pickSting(opts, rand) };
}
